WITH flattened_attrs AS (SELECT id, plan, effective_from, currency, tier_limits, tier_prices, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT *, FIRST_VALUE(avg_tier_price, TRUE) OVER (ORDER BY avg_tier_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_avg_tier_price, AVG(avg_tier_price) OVER w_ordered AS avg_tier_price_avg_6, ROW_NUMBER() OVER (PARTITION BY currency ORDER BY avg_tier_price DESC, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY currency, plan ORDER BY effective_from DESC, id) AS row_seq, AVG(avg_tier_price) OVER (PARTITION BY plan) AS plan_avg_avg_tier_price FROM flattened_attrs WHERE avg_tier_price < 20 WINDOW w_ordered AS (ORDER BY effective_from, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)
